/* @autogenerated */
package net.civeira.phylax.feature.observe.slo;

import java.util.List;

import net.civeira.phylax.feature.observe.metric.Histogram;
import net.civeira.phylax.feature.observe.metric.MetricPoint;

/**
 * Arithmetic of the objectives over RED metric points: good and total requests, compliance, error
 * budget and burn rate (how many times faster than allowed the budget is spent: 1 spends it exactly
 * in the window).
 */
public final class SloMath {

  /** Multiwindow burn-rate policy (Google SRE workbook): fast 1 h / 5 min, slow 6 h / 30 min. */
  public static final double FAST_BURN = 14.4;
  public static final double SLOW_BURN = 6;

  private SloMath() {}

  /** Good and total requests of some points. */
  public record Counts(long good, long total) {
    public double badRatio() {
      return total == 0 ? 0 : (double) (total - good) / total;
    }
  }

  /**
   * @param latencyMs null for availability; for latency, the limit of a good request (rounded down
   *        to a bucket limit)
   */
  public static Counts counts(final List<MetricPoint> points, final String route,
      final Integer latencyMs, final long from, final long to) {
    long good = 0;
    long total = 0;
    int last = null == latencyMs ? -1 : bucketIndex(latencyMs);
    for (MetricPoint point : points) {
      if (point.ts() < from || point.ts() >= to
          || (null != route && !route.isBlank() && !route.equals(point.route()))) {
        continue;
      }
      total += point.count();
      if (null == latencyMs) {
        good += point.count() - point.errors();
      } else if (null != point.buckets()) {
        for (int i = 0; i <= last && i < point.buckets().length; i++) {
          good += point.buckets()[i];
        }
      }
    }
    return new Counts(good, total);
  }

  /** Index of the last bucket whose limit is below or equal to {@code latencyMs} (-1 if none). */
  static int bucketIndex(final int latencyMs) {
    int index = -1;
    for (int i = 0; i < Histogram.LIMITS.length; i++) {
      if (Histogram.LIMITS[i] <= latencyMs) {
        index = i;
      }
    }
    return index;
  }

  /** Burn rate: share of bad requests divided by the share the objective allows. */
  public static double burn(final Counts counts, final double objective) {
    double allowed = 1 - objective;
    return counts.total() == 0 || allowed <= 0 ? 0 : counts.badRatio() / allowed;
  }

  /** Remaining error budget of the window, as a fraction (1 untouched, 0 spent, negative over). */
  public static double budgetRemaining(final Counts counts, final double objective) {
    return 1 - burn(counts, objective);
  }
}
